(()=>{
const M=SACCR,{m,n,pct,slider,select,bars,add}=SACCR_UI;
add({id:'saccr-portfolio',name:'A portfolio from trades to EAD',stage:'04 · Putting the framework together',title:'Follow a small portfolio all the way to exposure value',intro:'Calculate trade risk positions, build the asset-class add-ons, sum them, apply the PFE multiplier and add replacement cost before alpha.',chart:'Exposure construction for one unmargined netting set',inputs:[slider('scale','Portfolio notional scale',0,200,5,100,'%'),slider('v','Current net market value',-30,30,1,8),slider('nica','Eligible net independent collateral',-10,40,1,5),select('type','2027 counterparty category',[['financial','Other counterparty · alpha 1.4'],['nfc','Defined non-financial / pension · alpha 1']],'financial')],challenge:'Set current market value below collateral. Does PFE vanish with replacement cost?',formula:'Trade risk position = δ × adjusted notional × MF\nAggregate add-on = sum of asset-class add-ons\nPFE = multiplier × aggregate add-on\nRC = max(CMV − NICA, 0)\nEAD = α × (RC + PFE)',key:'Each example is a positive linear risk position in an ordinary hedging set. All maturities are at least one year, so unmargined MF = 1. No cross-class diversification is applied.',simple:'Each stage answers a different question. Trade features determine risk positions; grouping determines offsets; collateral affects today’s gap and the PFE cushion. Alpha is applied only after RC and PFE have been assembled.',scope:'One legally recognised unmargined netting set with six representative trades. All notionals are in reporting-currency millions: IR 100, FX 60, credit 20, equity 10, commodity 20, other 5, scaled by the control. IR and credit start now and end at 5 years; others end at 1 year. No transition add-on or special exceptions.',rule:'Articles 274–280f',compute(s){const f=s.scale/100,ds=M.sd(0,5),names=['Interest rate','FX','Credit CQS 3','Single equity','Commodity · oil','Other risk'],not=[100,60,20,10,20,5].map(x=>x*f),adj=not.map((x,i)=>i===0||i===2?x*ds:x),sf=[.005,.04,.0054,.32,.18,.08],a=adj.map((x,i)=>x*sf[i]),agg=M.sum(a),alpha=s.type==='financial'?1.4:1,r=M.ead({...s,vm:0,th:0,mta:0,alpha},agg,false);return {stats:[['Exposure value',m(r.ead)],['Aggregate add-on',m(agg)],['PFE multiplier',pct(r.mult)]],bars:bars(['Replacement cost','PFE','Alpha uplift','EAD'],[r.rc,r.pfe,r.ead-r.rc-r.pfe,r.ead]),headers:['Trade / stage','Notional','Adjusted notional / input','Factor','Add-on / result'],rows:[...names.map((v,i)=>[v,m(not[i]),m(adj[i]),pct(sf[i]),m(a[i])]),['Aggregate add-on','—','—','Sum',m(agg)],['Replacement cost','—',m(s.v-s.nica),'Positive part',m(r.rc)],['PFE','—',m(agg),pct(r.mult),m(r.pfe)],['EAD','—',m(r.rc+r.pfe),'Alpha '+alpha,m(r.ead)]],explanation:'The six add-ons total '+m(agg)+'. The multiplier reduces this to PFE of '+m(r.pfe)+'. Adding replacement cost '+m(r.rc)+' and applying alpha '+alpha+' gives EAD of '+m(r.ead)+'.',note:'These asset supervisory factors are not counterparty credit-risk weights. EAD is an input to the subsequent RWA calculation, not RWA itself.'};}});
add({id:'saccr-margin-cap',name:'Margin cap and agreement structure',stage:'04 · Putting the framework together',title:'Margined exposure is capped by the unmargined comparison',intro:'After calculating the same netting set under both treatments, Article 274(3) caps the margined exposure at the result without a margin agreement.',chart:'Before and after the margined exposure cap',inputs:[slider('mr','Valid margined RC',0,40,1,2),slider('mp','Valid margined PFE',0,40,1,8),slider('ur','Same-set unmargined RC',0,40,1,5),slider('up','Same-set unmargined PFE',0,40,1,12)],challenge:'Make the margined calculation larger than the unmargined comparison. Which value is finally used?',formula:'Margined candidate = 1.4 × (RCm + PFEm)\nUnmargined comparator = 1.4 × (RCu + PFEu)\nCapped exposure = min(margined candidate, unmargined comparator)',key:'The cap compares two complete calculations for the same netting set. It does not mean substituting the smaller RC and smaller PFE separately.',simple:'A margin agreement should not make the standardised exposure exceed the no-margin comparison. But the comparison has to be internally consistent: calculate each branch under its own rules, then apply the cap to the totals.',scope:'The four controls are independently supplied outputs of otherwise valid same-set calculations, not a model of one specific trade portfolio. Alpha 1.4 is fixed. Conditional legacy alpha add-ons are outside this cap illustration.',rule:'Articles 274(3)–(4), 275(3) and 278(2)',notes:[['Multiple agreements within one netting set','Article 274(4) requires sub-netting sets for PFE: unmargined and post-only trades together, and margined trades grouped by common MPOR. Sum the sub-netting-set aggregate add-ons as specified.'],['One agreement covering multiple legal netting sets','Shared collateral does not merge the legal sets. Article 275(3) has a dedicated RC formula. Article 278(2) sums their PFE calculated as if unmargined. The single-set multiplier formula must not be applied blindly to the merged values.']],compute(s){const a=1.4*(s.mr+s.mp),b=1.4*(s.ur+s.up),e=Math.min(a,b);return {stats:[['Capped exposure',m(e)],['Cap reduction',m(a-e)],['Binding branch',a>b?'Unmargined cap':'Margined result']],bars:bars(['Margined candidate','Unmargined comparator','Final exposure'],[a,b,e]),headers:['Branch','RC','PFE','EAD'],rows:[['Margined',m(s.mr),m(s.mp),m(a)],['Unmargined comparison',m(s.ur),m(s.up),m(b)],['Final','—','—',m(e)]],explanation:'The final exposure is '+m(e)+'. '+(a>b?'The unmargined comparator caps the larger margined candidate.':'The margined candidate is already at or below the comparator, so the cap does not reduce it.'),note:'Margin agreement structure is a calculation input, not merely a documentation detail.'};}});
add({id:'saccr-alpha',name:'UK alpha and legacy transition',stage:'04 · Putting the framework together',title:'Use the UK counterparty treatment and the right transition base',intro:'From 2027 the PRA sets alpha to 1 for defined non-financial and pension-related counterparties. Some legacy transactions retain a conditional, declining alpha add-on.',chart:'Exposure with the conditional legacy add-on',inputs:[select('type','Counterparty category',[['financial','Other counterparty · alpha 1.4'],['eligible','Defined non-financial / pension-related · alpha 1']],'eligible'),slider('current','Current RC + PFE',0,100,1,30),slider('base','1 January 2027 RC + PFE base',0,100,1,20),select('year','Calculation year',[['2027','2027'],['2028','2028'],['2029','2029'],['2030','2030 onward']],'2027'),select('legacy','Legacy / CVA transition conditions',[['yes','All applicable conditions satisfied; treatment continues'],['no','Not applicable or CVA transition ceased']],'no')],challenge:'Keep the January 2027 base fixed and grow the current exposure. Is the transitional add-on a percentage of today’s exposure?',formula:'Base alpha add-on = EAD at 1 Jan 2027 with α 1.4 − EAD at 1 Jan 2027 with α 1\nCurrent exposure = current α × (RC + PFE) + applicable fraction × base alpha add-on\nFractions: 60% in 2027; 40% in 2028; 20% in 2029; none thereafter',key:'The base is frozen at 1 January 2027. Article 274(2A) depends on pre-2027 transactions, the referenced counterparty conditions and continuing CVA transition treatment. It does not apply to leverage-ratio calculation under 274(2B).',simple:'The new alpha treatment and the legacy add-on are two separate steps. The add-on runs off a fixed starting snapshot; it is not a new universal alpha multiplied by every current portfolio.',scope:'A simplified homogeneous eligible legacy netting set for which the two starting exposure values differ by 0.4 × the supplied base. No exceptional caps or mixed legacy/new portfolio allocation is modelled. The eligibility choice assumes the complete legal conditions, rather than checking them.',rule:'Article 274(2), (2A), (2B) and definition of alpha add-on',sources:[['https://www.bankofengland.co.uk/-/media/boe/files/prudential-regulation/policy-statement/2026/january/ps126app1.pdf#page=456','PRA2026/1 Annex R · alpha amendments'],['https://www.bankofengland.co.uk/-/media/boe/files/prudential-regulation/policy-statement/2026/january/ps126app1.pdf#page=423','CVA Risk 7.1 · linked transition conditions']],compute(s){const alpha=s.type==='financial'?1.4:1,eligible=s.type==='eligible'&&s.legacy==='yes',rate={'2027':.6,'2028':.4,'2029':.2,'2030':0}[s.year],f=eligible?rate:0,base=.4*s.base,extra=f*base,e=alpha*s.current+extra;return {stats:[['Exposure value',m(e)],['Current alpha',alpha.toFixed(1)],['Legacy add-on',m(extra)]],bars:bars(['2027','2028','2029','2030 onward'],[.6,.4,.2,0].map(x=>alpha*s.current+(eligible?x*base:0))),headers:['Step','Value','Basis'],rows:[['Current pre-alpha exposure',m(s.current),'Current RC + PFE'],['Current alpha',alpha,'Counterparty category'],['Frozen alpha add-on',m(base),'0.4 × supplied 1 Jan 2027 base'],['Applicable fraction',pct(f),'Year and continuing eligibility'],['Legacy addition',m(extra),'Fraction × frozen add-on'],['Current exposure',m(e),'Current base exposure plus legacy addition']],explanation:'Current exposure is '+m(e)+', including a legacy addition of '+m(extra)+'. '+(eligible?'The addition uses the frozen January 2027 base, not today’s RC plus PFE.':'No legacy addition applies under the selected conditions.'),note:'The chart holds today’s exposure and the frozen base constant to isolate the phase-out schedule; it is not a forecast.'};}});
})();

